// === CLEAN + NORMALIZE ===
// Maps Apify Google Maps Scraper output → canonical lead shape.
// Safe against null/undefined/missing fields.

const out = [];

for (const item of items) {
  const raw = item.json || {};

  const normPhone = (p) => {
    if (!p) return null;
    const s = String(p).replace(/[^0-9+]/g, '');
    return s.length >= 7 ? s : null;
  };

  const normWebsite = (w) => {
    if (!w) return null;
    const s = String(w).trim().toLowerCase();
    if (!s || s === 'n/a' || s === 'null' || s === 'undefined') return null;
    // Treat Google's own placeholder pages as no-website.
    if (s.includes('business.google.com') || s.includes('g.co/')) return null;
    return s;
  };

  const lead = {
    business_name: raw.title || raw.name || null,
    phone: normPhone(raw.phone || raw.phoneUnformatted),
    address: raw.address || raw.street || null,
    city: raw.city || null,
    website: normWebsite(raw.website),
    rating: typeof raw.totalScore === 'number' ? raw.totalScore : (typeof raw.rating === 'number' ? raw.rating : null),
    reviews_count: typeof raw.reviewsCount === 'number' ? raw.reviewsCount : (typeof raw.reviews === 'number' ? raw.reviews : 0),
    category: raw.categoryName || (Array.isArray(raw.categories) ? raw.categories[0] : null),
    place_id: raw.placeId || raw.cid || null,
    latitude: raw.location ? raw.location.lat : null,
    longitude: raw.location ? raw.location.lng : null,
    source: 'google_maps_apify',
    scraped_at: new Date().toISOString(),
  };

  out.push({ json: lead });
}

return out;

// === FILTER: HIGH-PRIORITY LEADS (single-output) ===
const out = [];

for (const item of items) {
  const l = item.json || {};

  const noWebsite  = l.website === null || l.website === '' || l.website === undefined;
  const hasPhone   = typeof l.phone === 'string' && l.phone.replace(/\D/g, '').length >= 7;
  const hasName    = typeof l.business_name === 'string' && l.business_name.trim().length > 0;
  const lowRating  = l.rating == null || Number(l.rating) < 4.2;
  const lowReviews = (l.reviews_count ?? 0) < 50;

  if (hasName && noWebsite && hasPhone && lowRating && lowReviews) {
    out.push({ json: { ...l, priority: 'high' } });
  }
}

return out;

// Log rejected leads (optional sink — write to a separate sheet tab or just console).
console.log(`Rejected ${items.length} leads:`, items.map(i => ({ name: i.json.business_name, reasons: i.json.rejection_reasons })));
return items;
